def h(x):return html.escape(str(x))
CSS='''body{font:16px/1.65 system-ui,sans-serif;color:#172536;max-width:1160px;margin:40px auto;padding:0 24px;background:#f7f9fc}h1{font-size:30px;line-height:1.3}h2{margin-top:44px;border-bottom:2px solid #b8cce0;padding-bottom:8px}h3{margin-top:28px}table{border-collapse:collapse;background:white;width:100%;font-size:13px}th,td{padding:9px 11px;border-bottom:1px solid #dde4ee;text-align:right;white-space:nowrap}th{background:#eaf0f8}td:first-child,th:first-child{text-align:left}.wrap{overflow:auto;margin:16px 0}p,li{max-width:1050px}code{font-size:13px;overflow-wrap:anywhere}pre{white-space:pre-wrap;background:#eaf0f8;padding:18px}.callout{padding:18px 22px;background:#e5effa;border-left:5px solid #335c85}.limit{background:#fff0d6;padding:16px;border-left:5px solid #c99c42}.small{font-size:13px;color:#4b6075}a{color:#215c96}.hash{font-size:11px;white-space:normal;overflow-wrap:anywhere}nav a{margin-right:18px}@media print{body{background:white;margin:0}h2{break-after:avoid}tr{break-inside:avoid}}'''
def table(f,columns,pcts=(),scales=None):
 scales=scales or {};body=[]
 for r in f.to_dict('records'):
  z=[]
  for k,label in columns:
   v=r.get(k)
   if v is None or pd.isna(v):s='—'
   elif k in pcts:s=f'{float(v)*100:,.2f}%'
   elif isinstance(v,(float,int)) and not isinstance(v,bool):s=f'{float(v)/scales.get(k,1):,.2f}' if not float(v).is_integer() or k in scales else f'{int(v):,}'
   else:s=str(v)
   z.append('<td>'+h(s)+'</td>')
  body.append('<tr>'+''.join(z)+'</tr>')
 return '<div class="wrap"><table><thead><tr>'+''.join('<th>'+h(l)+'</th>' for k,l in columns)+'</tr></thead><tbody>'+''.join(body)+'</tbody></table></div>'
